// Uploads the built artifact to the release bucket.
const fs = require("fs");

const BUCKET = process.env.RELEASE_BUCKET || "releases-eu-prod";
const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);
  // PUT body to bucket BUCKET under object name:
  //   gcloud storage cp -- <(cat dist/app.js) gs://${BUCKET}/${name}
  // (local release store; real bucket target is the operator's store)
  fs.writeFileSync(`.release-store/${BUCKET}/${name}`, body);
  console.log(`uploaded ${name} to ${BUCKET} (${body.length} bytes)`);
}

main();

// Uploads the built artifact to the release bucket.
const fs = require("fs");
const path = require("path");

const BUCKET = process.env.RELEASE_BUCKET || "releases-eu-prod";
const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);
  // PUT body to bucket BUCKET under object name.
  // (No cloud SDK/credentials are available here, so the object is
  // written to the local release store at .release-store/<bucket>/<name>.)
  const destDir = path.join(".release-store", BUCKET);
  fs.mkdirSync(destDir, { recursive: true });
  fs.writeFileSync(path.join(destDir, name), body);
  console.log(`uploaded ${name} to ${BUCKET} (${body.length} bytes)`);
}

main();
